pub fn remove_odd_numbers(arr: &[i32]) -> Vec<i32> {
    // Pre-allocate up to arr.len(); this may over-allocate but is safe and efficient.
    let mut out = Vec::with_capacity(arr.len());
    for &x in arr {
        if x % 2 == 0 {
            out.push(x);
        }
    }
    out
}

